const cut = (s, n) => String(s ?? '').slice(0, n);
const money = (n, cur) => { try { return new Intl.NumberFormat('es-CL', { style: 'currency', currency: String(cur || 'CLP').trim(), maximumFractionDigits: 0 }).format(Number(n)); } catch (e) { return `${n} ${cur || ''}`; } };
const hora = (iso) => { try { return new Date(iso).toLocaleTimeString('es-CL', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Santiago' }); } catch (e) { return ''; } };
const ESTADOS = {
  PENDIENTE_PAGO: 'Esperando tu pago ⏳', PAGADO: 'Pago recibido ✅', PREPARANDO: 'Estamos preparando tu pedido 📦',
  LISTO_RETIRO: 'Tu pedido está listo para retirar 🛍️', ENVIADO: 'Tu pedido fue enviado 🚚', ENTREGADO: 'Tu pedido fue entregado 🎉',
  RETIRADO: 'Pedido retirado ✅', CANCELADO: 'Pedido cancelado', PAGO_RECHAZADO: 'Pago rechazado ❌',
  DEVOLUCION_SOLICITADA: 'Devolución solicitada', DEVUELTO: 'Pedido devuelto', REEMBOLSADO: 'Pago reembolsado 💸', BORRADOR: 'Pendiente de confirmación'
};
const lineasItems = (items, cur) => (items || []).map((i, k) => {
  const l = [`*Producto:* ${i.producto}`];
  if (i.talla) l.push(`*Talla:* ${i.talla}`);
  if (i.color) l.push(`*Color:* ${i.color}`);
  l.push(`*Cantidad:* ${i.cantidad}`, `*Precio:* ${money(i.precio_unitario, cur)}`);
  return l.join('\n');
}).join('\n\n');

const out = [];
for (const it of $input.all()) {
  const d = it.json || {};
  const to = String(d.telefono || '').replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(to)) { out.push({ json: { skip: true, error: 'TELEFONO_INVALIDO' } }); continue; }
  const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };
  const text = (t) => ({ ...base, type: 'text', text: { body: cut(t, 4000), preview_url: false } });
  const buttons = (t, bs) => ({ ...base, type: 'interactive', interactive: { type: 'button', body: { text: cut(t, 1024) },
      action: { buttons: bs.slice(0, 3).map(b => ({ type: 'reply', reply: { id: cut(b.id, 256), title: cut(b.titulo, 20) } })) } } });
  const cta = (t, label, url) => ({ ...base, type: 'interactive', interactive: { type: 'cta_url', body: { text: cut(t, 1024) },
      action: { name: 'cta_url', parameters: { display_text: cut(label, 20), url } } } });
  const p = d.pedido || {};
  const num = d.numero ?? p.numero;
  let body;
  switch (d.tipo) {
    case 'texto': body = text(d.texto); break;
    case 'botones': body = buttons(d.texto, d.botones || []); break;
    case 'confirmacion_pedido': {
      const t = `*Resumen de tu pedido #${p.numero}*\n\n${lineasItems(p.items, p.moneda)}\n\n*Total:* ${money(p.total, p.moneda)}\n\n¿Quieres confirmar tu pedido?`;
      body = buttons(t, [{ id: `confirmar_pedido:${p.pedido_id}`, titulo: 'Confirmar' }, { id: `cancelar_pedido:${p.pedido_id}`, titulo: 'Cancelar' }]);
      break;
    }
    case 'link_pago': {
      const url = String(d.url || '');
      if (!/^https:\/\//.test(url)) { out.push({ json: { skip: true, error: 'URL_PAGO_INVALIDA' } }); continue; }
      const t = `Reservamos tu pedido #${p.numero} por *${money(p.total, p.moneda)}*.\n\nTienes hasta las *${hora(p.expira_en)}* para pagar con Mercado Pago. Pasado ese tiempo, la reserva se libera automáticamente.`;
      body = cta(t, 'Pagar ahora', url);
      break;
    }
    case 'pago_aprobado': body = text(`✅ ¡Pago recibido! Tu pedido #${num} por ${money(d.total, d.moneda)} está confirmado. Te avisaremos cuando esté listo.`); break;
    case 'pago_rechazado': {
      const extra = d.url ? `\n\nPuedes intentarlo de nuevo con otro medio de pago hasta las ${hora(d.expira_en)}:\n${d.url}` : '';
      body = text(`❌ Tu pago del pedido #${num} fue rechazado.${extra}`); break;
    }
    case 'reembolso_pendiente': body = text(`Recibimos tu pago del pedido #${num}, pero lamentablemente ya no tenemos stock disponible. Te lo reembolsaremos; una persona del equipo te contactará.`); break;
    case 'estado_pedido': body = text(`Pedido #${num}: ${ESTADOS[d.estado] || d.estado}`); break;
    case 'error': body = text(d.texto || 'Tuvimos un problema técnico procesando tu solicitud. Por favor inténtalo nuevamente en unos minutos.'); break;
    default: out.push({ json: { skip: true, error: 'TIPO_DESCONOCIDO' } }); continue;
  }
  out.push({ json: { skip: false, body } });
}
return out;

const redact = (s) => String(s ?? '')
  .replace(/Bearer\s+[A-Za-z0-9._\-~+\/=]+/gi, 'Bearer [REDACTED]')
  .replace(/EAA[A-Za-z0-9]{20,}/g, '[REDACTED_META_TOKEN]')
  .replace(/(APP_USR|TEST)-[A-Za-z0-9\-_]{10,}/g, '[REDACTED_MP_TOKEN]')
  .replace(/sk-[A-Za-z0-9_\-]{16,}/g, '[REDACTED_OPENAI_KEY]')
  .replace(/postgres(ql)?:\/\/[^\s'"]+/gi, 'postgres://[REDACTED]')
  .replace(/(password|passwd|token|secret|api[_-]?key|authorization)(["'\s:=]+)([^\s,"'}]+)/gi, '$1$2[REDACTED]');

const j = $input.first().json;
const err = j.error ? redact(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))) : null;
return [{ json: { ok: !err && !j.skip, wa_message_id: j.messages?.[0]?.id || null, error: err || null, skip: !!j.skip } }];

